318  otError Message::SetPayloadMarker(void)
   319  {
   320      otError error  = OT_ERROR_NONE;
   321      uint8_t marker = 0xff;
   322
   323      VerifyOrExit(GetLength() < kMaxHeaderLength, error = OT_ERROR_NO_BUFS);
   324      SuccessOrExit(error = Append(&marker, sizeof(marker)));
   325      GetHelpData().mHeaderLength = GetLength();
   326
   327  exit:
   328      return error;
   329  }
